ValidationRule.errorConditionFormula:
/* S3（濃縮版）：僅針對 DR 場景啟動；含 EHD/CC/B2B 豁免 */
IF(
  $UserRole.Name = "System Administrator",
  FALSE,
  AND(
    OR(ISCHANGED(Status__c), ISCHANGED(Approval_Status__c)),

    /* 僅在 DR（當前或前一筆為 DR）時進入 S3 判斷 */
    OR(
      TEXT(Approval_Status__c) = "Documents Required",
      TEXT(PRIORVALUE(Approval_Status__c)) = "Documents Required"
    ),

    /* 不在允許條件才擋下 */
    NOT(
      OR(
        /* 未變更：放行 */
        AND(
          TEXT(PRIORVALUE(Status__c)) = TEXT(Status__c),
          TEXT(PRIORVALUE(Approval_Status__c)) = TEXT(Approval_Status__c)
        ),

        /* DR 相關白名單：放行 */
        CONTAINS(
          ";" &
          "Reapplied|Documents Required>Replied|Documents Required;" &
          "Reapplied|Documents Required>Reapplied|In Progress;" &
          "Closed|Documents Required>Reapplied|In Progress;" &
          "Replied|Documents Required>Reapplied|Documents Required;" &
          "Replied|Documents Required>Closed|Documents Required;" &
          ";",
          ";" &
          TEXT(PRIORVALUE(Status__c)) & "|" & TEXT(PRIORVALUE(Approval_Status__c)) &
          ">" &
          TEXT(Status__c) & "|" & TEXT(Approval_Status__c) & ";"
        ),

        /* 角色豁免：放行 */
        OR(
          /* S5 Step 3：IP|IP -> IP|DR（僅 EHD）*/
          AND(
            TEXT(PRIORVALUE(Status__c)) = "In Progress",
            TEXT(PRIORVALUE(Approval_Status__c)) = "In Progress",
            TEXT(Status__c) = "In Progress",
            TEXT(Approval_Status__c) = "Documents Required",
            CONTAINS($UserRole.Name, "EHD")
          ),
          /* S5 Step 4：In Progress|DR -> Replied|DR（僅 RMS）*/
         AND(
            TEXT(PRIORVALUE(Status__c)) = "In Progress",
            TEXT(PRIORVALUE(Approval_Status__c)) = "Documents Required",
            TEXT(Status__c) = "Replied",
            TEXT(Approval_Status__c) = "Documents Required",
            CONTAINS($UserRole.Name, "RMS")
          ),
          /* S3 Step 5：Reapplied|IP -> Reapplied|DR（僅 EHD）*/
          AND(
            TEXT(PRIORVALUE(Status__c)) = "Reapplied",
            TEXT(PRIORVALUE(Approval_Status__c)) = "In Progress",
            TEXT(Status__c) = "Reapplied",
            TEXT(Approval_Status__c) = "Documents Required",
            CONTAINS($UserRole.Name, "EHD")
          ),

          /* S3 Step 7：Replied|DR -> Reapplied|DR / Closed|DR（僅 CC/B2B）*/
          AND(
            TEXT(PRIORVALUE(Status__c)) = "Replied",
            TEXT(PRIORVALUE(Approval_Status__c)) = "Documents Required",
            OR(TEXT(Status__c) = "Reapplied", TEXT(Status__c) = "Closed"),
            TEXT(Approval_Status__c) = "Documents Required",
            OR(CONTAINS($UserRole.Name, "CC"), CONTAINS($UserRole.Name, "B2B"))
          )
        )
      )
    )
  )
)
